 where a.eid in (select distinct eid from expected) and not exists(select 1 from expected e where e.eid=a.eid and e.kind=a.kind and e.slot=a.slot)
 group by a.kind,a.eid,a.slot
)
select jsonb_build_object('batch','e11','expected_rows',(select count(*) from checked),'final_rows',(select count(*) from checked where matches=1 and final_matches=1),'old_rows',(select count(*) from checked where matches=1 and old_matches=1),'missing',(select count(*) from checked where matches=0),'duplicate_slots',(select count(*) from checked where matches>1),'mismatches',coalesce((select jsonb_agg(jsonb_build_object('qid',qid,'kind',kind,'slot',slot,'expected_id',rid,'expected_md5',new_md5,'matches',matches,'old_matches',old_matches,'actual',actual)) from checked where matches<>1 or final_matches<>1),'[]'::jsonb),'extra_slots',coalesce((select jsonb_agg(to_jsonb(extras)) from extras),'[]'::jsonb)) audit;
